#!/usr/bin/env bash
set -euo pipefail
TARGET=/opt/gsc-autopilot
sudo mkdir -p /opt
echo '' | base64 -d | sudo tar -xzf - -C /opt
sudo chown -R "$(id -un):$(id -gn)" "$TARGET"
cd "$TARGET"
if command -v gcloud >/dev/null 2>&1; then
  gcloud services enable searchconsole.googleapis.com --quiet || true
fi
docker compose -f compose.yml up -d --build
sleep 10
docker logs --tail 100 gsc-autopilot
